svg.script:
(function(){
var $=function(i){return document.getElementById(i)};
// Single source of truth: el, total elapsed time in integer microseconds (BigInt).
// Dots, counts and the clock are all derived from it each frame.
var US=1000000n,Y=31557600n;
var Pm=[US,3n*86400n*US,1000n*Y*US],Lm=[100n*Y*US,1000000n*Y*US,1000000000n*Y*US],BD=10n**15n*Y*US;
var P=[1,3*86400,1000*31557600];
var CX=[170,450,730],CY=190,R=100,MAXE=22,LIM=15,X0=150,X1=750;
var e=0,el=0n,rem=0,last=null,drag=false,note=0,shownE=-1;
var d=[$('d0'),$('d1'),$('d2')],b=[$('b0'),$('b1'),$('b2')],wa=[$('w0a'),$('w1a'),$('w2a')],wb=[$('w0b'),$('w1b'),$('w2b')],c=[$('c0'),$('c1'),$('c2')],l=[$('l0'),$('l1'),$('l2')];
var Ys=31557600,U=[[1,'s'],[60,'min'],[3600,'h'],[86400,'d'],[Ys,'y'],[Ys*1e3,'ky'],[Ys*1e6,'my'],[Ys*1e9,'by'],[Ys*1e12,'ty']],S=[[1e3,'k'],[1e6,'m'],[1e9,'b'],[1e12,'t']];
function f3(v){return v>=100?Math.round(v):v>=10?v.toFixed(1):v.toFixed(2);}
function sup(n){return String(n).replace(/\d/g,function(x){return '⁰¹²³⁴⁵⁶⁷⁸⁹'[x]});}
// Counts: k, m, b, t up to 999t; exponents only beyond that.
function abbr(n){
 if(n*1.0005<1e3)return Math.floor(n).toLocaleString('en-US');
 if(n>=1e15){var x=Math.floor(Math.log10(n)),m=n/Math.pow(10,x);
  if(m.toFixed(2)==='10.00'){m=1;x++;}return m.toFixed(2)+'×10'+sup(x);}
 var i=3;while(i>0&&n*1.0005<S[i][0])i--;
 return f3(n/S[i][0])+S[i][1];
}
// Time: y, ky, my, by, ty.
function dur(s){
 var i=0;while(i<U.length-1&&s*1.005>=U[i+1][0])i++;
 return f3(s/U[i][0])+' '+U[i][1];
}
function num(n){return abbr(n);}
// Blur: two standing-wave bands (R±A·sin(nθ+φ)) bent around the circle.
// Bumps per circle grow with laps/s; the two bands use a 2:3 pair of counts and turn in opposite directions.
var NP=360,TH=[],CS=[],SN=[];
for(var q=0;q<NP;q++){var th=2*Math.PI*q/NP;TH.push(th);CS.push(Math.cos(th));SN.push(Math.sin(th));}
function wave(cx,n,amp,ph){
 var a='',b='',w,r1,r2;
 for(var q=0;q<NP;q++){w=amp*Math.sin(n*TH[q]+ph);r1=R+w;r2=R-w;
  a+=(q?'L':'M')+(cx+r1*CS[q]).toFixed(1)+' '+(CY+r1*SN[q]).toFixed(1);
  b+=(q?'L':'M')+(cx+r2*CS[q]).toFixed(1)+' '+(CY+r2*SN[q]).toFixed(1);}
 return a+'Z'+b+'Z';
}
var k=$('knob'),svg=k.ownerSVGElement;
function draw(t){
 var s=Math.pow(10,e),sec=Number(el)/1e6;
 if(e!==shownE){shownE=e;k.setAttribute('cx',X0+(X1-X0)*e/MAXE);
  k.setAttribute('aria-valuenow',e.toFixed(2));k.setAttribute('aria-valuetext',dur(s)+' per second');}
 $('read').textContent=dur(s)+' / s';
 $('el').textContent=dur(sec);
 $('note').textContent=t<note?'Black dwarf. Time reset.':'';
 for(var i=0;i<3;i++){
  var blurred=s/P[i]>LIM,life=el>=Lm[i];
  b[i].style.display=blurred?'':'none';
  d[i].style.display=blurred?'none':'';
  if(!blurred){var a=Number(el%Pm[i])/Number(Pm[i])*2*Math.PI-Math.PI/2;
   d[i].setAttribute('cx',CX[i]+R*Math.cos(a));d[i].setAttribute('cy',CY+R*Math.sin(a));}
  else{var L=Math.log10(s/P[i]/LIM),n=Math.round(3+1.2*L),n2=Math.round(n*1.5),sp=1+Math.min(0.04*L,0.8),T=t/1000;
   if(n2===n)n2=n+1;
   wa[i].setAttribute('d',wave(CX[i],n,9,n*0.6*sp*T));
   wb[i].setAttribute('d',wave(CX[i],n2,6,-n2*0.9*sp*T));}
  c[i].textContent=num(Number(life?el/Lm[i]:el/Pm[i]));
  l[i].textContent=life?(el/Lm[i]===1n?'lifetime':'lifetimes'):'cycles';
 }
}
function tick(t){
 if(last!==null){
  var dt=Math.min((t-last)/1000,0.1),x=dt*Math.pow(10,e)*1e6+rem,inc=Math.round(x);
  rem=x<1e15?x-inc:0;
  el+=BigInt(inc);
  if(el>=BD){el=0n;rem=0;note=t+2500;}
 }
 last=t;draw(t);requestAnimationFrame(tick);
}
function set(ev){
 var p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;
 var x=p.matrixTransform(svg.getScreenCTM().inverse()).x;
 e=Math.max(0,Math.min(MAXE,(x-X0)/(X1-X0)*MAXE));
}
var g=$('ctl');
g.addEventListener('pointerdown',function(ev){drag=true;g.setPointerCapture(ev.pointerId);set(ev);});
g.addEventListener('pointermove',function(ev){if(drag)set(ev);});
g.addEventListener('pointerup',function(){drag=false;});
g.addEventListener('pointercancel',function(){drag=false;});
k.addEventListener('keydown',function(ev){
 if(ev.key==='ArrowRight'||ev.key==='ArrowUp')e=Math.min(MAXE,e+0.25);
 else if(ev.key==='ArrowLeft'||ev.key==='ArrowDown')e=Math.max(0,e-0.25);
});
draw(0);requestAnimationFrame(tick);
})();
